    /**
     * Handles loading a Note using a UUID
     * @param		UUID uuid 
     * @return		Note
     */    
    @GetMapping("/load")
    public Note load( @RequestParam(required=true) UUID uuid ) {    	
    	Note entity = null;

    	try {  
    		entity = service.getNote( new NoteFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Note using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Note business objects
     * @return		Set<Note>
     */
    @GetMapping("/")
    public List<Note> loadAll() {                
    	List<Note> noteList = null;
        
    	try {
            // load the Note
            noteList = service.getAllNote();
            
            if ( noteList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Notes" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Notes ", exc );
        	return null;
        }

        return noteList;
                            
    }

